bool FLyraRecoilEditOperations::CommitPattern(const FLyraRecoilPatternData& InData, const FText& Description, TArray<FString>& OutErrors)
{
    ULyraRecoilProfile* Target = Profile.Get();
    ULyraRecoilEditorSession* Sess = Session.Get();
    if (!Target) { OutErrors.Add(TEXT("没有正在编辑的 Profile。")); return false; }

    // 1) 无变化 → 不建事务、不标脏
    const FLyraRecoilPatternData Current = FLyraRecoilPatternAdapter::Read(*Target);
    if (FLyraRecoilPatternAdapter::Equal(Current, InData)) { return true; }

    // 2) 临时候选 Profile 上校验（不触发源对象通知/Dirty）
    ULyraRecoilProfile* Candidate = DuplicateObject<ULyraRecoilProfile>(Target, GetTransientPackage());
    if (!Candidate) { ... }
    Candidate->PatternPoints = InData.Points;
    Candidate->PatternLength = InData.PatternLength;
    Candidate->SanitizePatternLength();
    // 3) 正向重建校验
    TArray<FVector2D> CandidateCumulative;
    if (!FLyraRecoilPatternAdapter::BuildCumulative(*Candidate, CandidateCumulative, OutErrors)) return false;
    // 4) ValidateProfile
    TArray<FString> ValidationErrors;
    if (!Candidate->ValidateProfile(ValidationErrors)) { OutErrors.Append(...); return false; }
    if (!FLyraRecoilPatternAdapter::Validate(*Candidate, OutErrors)) return false;
    // 5) 还原检查：候选读回必须等于提交数据（不允许静默 sanitize 后仍声称成功）
    ...
}
```
