bool FLyraRecoilEditOperations::BuildCumulativePitchSortOrder(TArray<int32>& OutOrder, TArray<FString>& OutErrors) const
{
	const ULyraRecoilProfile* Target = Profile.Get();
	if (!Target)
	{
		OutErrors.Add(TEXT("没有正在编辑的 Profile。"));
		return false;
	}

	TArray<FVector2D> CumulativePoints;
	if (!FLyraRecoilPatternAdapter::BuildCumulative(*Target, CumulativePoints, OutErrors))
	{
		return false;
	}

	OutOrder.Reset();
	OutOrder.Reserve(CumulativePoints.Num());
	for (int32 Index = 0; Index < CumulativePoints.Num(); ++Index)
	{
		OutOrder.Add(Index);
	}

	// 稳定排序：按累计 Pitch 升序，相同值保持原顺序。
	OutOrder.StableSort([&CumulativePoints](int32 Left, int32 Right)
	{
		return CumulativePoints[Left].Y < CumulativePoints[Right].Y;
	});

	return true;
}

