void FLyraRecoilProfileEditor::RefreshFromAsset()
{
    if (!Profile) return;

    TArray<FString> Errors;
    CumulativePoints.Reset();
    if (!FLyraRecoilPatternAdapter::BuildCumulative(*Profile, CumulativePoints, Errors))
    {
        Diagnostics = Errors;
    }
    else if (Errors.Num() > 0)
