void FLyraRecoilProfileEditor::OnPasteCommand()
{
	if (!Profile)
	{
		return;
	}

	const int32 FirstNewIndex = Profile->PatternPoints.Num();

	TArray<FString> Errors;
	const bool bDone = Operations.PasteNormalizedFromClipboard(Errors);
	SetDiagnostics(Errors);

	if (!bDone)
	{
		ShowNotification(TEXT("粘贴被拒绝（详见诊断面板）。"), /*bIsError=*/true);
		return;
	}

	RefreshFromAsset();

	TArray<int32> NewSelection;
	for (int32 Index = FirstNewIndex; Index < Profile->PatternPoints.Num(); ++Index)
	{
		NewSelection.Add(Index);
	}
	SelectIndices(NewSelection, /*bAppend=*/false);
}

